            if (max > min) {
                break;
            }

            System.out.println(
                    "The maximum must be greater than the minimum."
            );
        }

        // The + 1 allows max to be included.
        int secretNumber = random.nextInt(max - min + 1) + min;

        System.out.println();
        System.out.println(
                "I'm thinking of a number between " + min + " and "
                + max + " (including both). Can you guess what it is?"
        );

        int guessesLeft = 5;
        int attempts = 0;
        boolean won = false;

        System.out.println("You have " + guessesLeft + " guesses.");

        while (guessesLeft > 0) {
            System.out.println();

            int guess = readInteger(keyboard, "Type a number: ");

            // An out-of-range number does not use a guess.
            if (guess < min || guess > max) {
                System.out.println(
                        "Your guess (" + guess + ") is out of the range ["
                        + min + ", " + max + "]. Please guess again "
                        + "within the range."
                );
                continue;
            }

            attempts++;
            System.out.println("Your guess is: " + guess);

            if (guess == secretNumber) {
                System.out.println(
                        "The number I was thinking of is: " + secretNumber
                );
                System.out.println(
                        "Congratulations! You guessed it in "
                        + attempts + " attempts!"
                );

                won = true;
                break;
            }

            guessesLeft--;

            if (guess < secretNumber) {
                System.out.println(
                        "Too low! You have " + guessesLeft + " guesses left."
                );
            } else {
                System.out.println(
                        "Too high! You have " + guessesLeft + " guesses left."
                );
            }
        }

